css:
.sl-hero-path {
  background-color: var(--smartlearn-bg);
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-body-font, system-ui, -apple-system, sans-serif);
  min-height: 80vh;
  display: flex;
  align-items: center;
  padding-block: clamp(3.5rem, 7vw, 6rem);
}
.sl-hero-path .sl-text-primary { color: var(--smartlearn-primary); }
.sl-hero-path .sl-text-emphasis {
  color: var(--smartlearn-text);
  font-family: var(--smartlearn-heading-font, var(--smartlearn-body-font, system-ui, -apple-system, sans-serif));
}
.sl-hero-path .sl-text-muted { color: var(--smartlearn-text-muted); }
.sl-hero-path .sl-bg-main { background-color: var(--smartlearn-bg); }
.sl-hero-path .sl-bg-card {
  background-color: var(--smartlearn-card-bg);
  border: 1px solid var(--smartlearn-card-border);
}
.sl-hero-path .sl-btn-primary {
  background-color: var(--smartlearn-btn-bg);
  border: 1px solid var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-path .sl-btn-primary:hover,
.sl-hero-path .sl-btn-primary:focus-visible {
  background-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  border-color: var(--smartlearn-btn-hover-bg, var(--smartlearn-primary-hover));
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-path .sl-path-title {
  letter-spacing: -0.03em;
}
.sl-hero-path .sl-path-line {
  top: 0;
  inset-inline-start: 0;
  width: 100%;
  height: 100%;
  z-index: 0;
  pointer-events: none;
}
[dir="rtl"] .sl-hero-path .sl-path-line {
  transform: scaleX(-1);
}
.sl-hero-path .sl-step-num {
  width: 50px;
  height: 50px;
  flex-shrink: 0;
  background-color: var(--smartlearn-btn-bg);
  color: var(--smartlearn-btn-text, #ffffff);
}
.sl-hero-path .sl-node {
  max-width: 400px;
  transition: transform 0.25s ease, box-shadow 0.25s ease, border-color 0.25s ease;
}
.sl-hero-path .sl-node-1 { margin-inline-start: 0; }
.sl-hero-path .sl-node-2 { margin-inline-start: 16%; }
.sl-hero-path .sl-node-3 { margin-inline-start: 32%; }
@media (prefers-reduced-motion: no-preference) {
  .sl-hero-path .sl-node:hover {
    transform: translateY(-4px);
    box-shadow: 0 15px 30px color-mix(in srgb, var(--smartlearn-primary) 18%, transparent);
    border-color: var(--smartlearn-primary);
  }
}
@media (prefers-reduced-motion: reduce) {
  .sl-hero-path .sl-node {
    transition: none;
  }
}
@media (max-width: 991px) {
  .sl-hero-path .sl-node-1,
  .sl-hero-path .sl-node-2,
  .sl-hero-path .sl-node-3 {
    margin-inline-start: 0;
    max-width: 100%;
  }
}
